def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(user_function):
        cache = {}
        use_count = {}
        call_count = 0
        def wrapper(*args, **kwargs):
            nonlocal call_count
            call_count += 1
            if args not in cache or (typed and kwargs and args not in cache):
                cache[args] = user_function(*args, **kwargs)
                use_count[args] = 1
            else:
                use_count[args] += 1
            if len(cache) > maxsize:
                for args, _ in sorted(use_count.items(), key=lambda x: x[1])[maxsize // 10]:
                    del cache[args]
                    del use_count[args]
            return cache[args]
        wrapper.cache = cache
        wrapper.use_count = use_count
        wrapper.call_count = call_count
        return wrapper
    return decorator
