        # Using the built-in function, read the version from the version.py file
        version = get_version_from_files(VERSION_PATH)
    except FileNotFoundError:
        # If the file does not exist, return the default value
        version = DEFAULT_VERSION
    except Exception as e:
        # If there is any other error, return the default value
        version = DEFAULT_VERSION
        print(f"Error: {str(e)}")
    return version

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if not isinstance(pieces, list):
        raise ValueError("Invalid type for pieces: expected list, got %s" % type(pieces).__name__)

    if not isinstance(style, str):
        raise ValueError("Invalid type for style: expected string, got %s" % type(style).__name__)

    render_fns = {
        "semantic": render_semantic_version,
        "pep440": render_pep440_version,
        "npm": render_npm_version,
        "deb": render_debian_version
    }

    if style not in render_fns:
        raise ValueError("Invalid style: %s" % style)

    return render_fns[style](pieces)

