def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for object_id in self._hierarchy.get_children(self._root_id):
        num_objects += 1
        object_str = self._hierarchy.get_object(object_id).get_object_string()
        if check_digests:
            expected_digest = self._hierarchy.get_digest(object_id)
            actual_digest = self._hash(object_str)
            if expected_digest != actual_digest:
                if show_warnings:
                    print(f"Warning: Object {object_id} has incorrect digest. Expected {expected_digest}, got {actual_digest}.")
                continue
        if validate_objects:
            try:
                obj = self._validate_object(object_str)
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Object {object_id} failed validation: {e}")
                continue
            if obj is None:
                if show_warnings:
                    print(f"Warning: Object {object_id} has validation error.")
                continue
            good_objects += 1
    return (num_objects, good_objects)
