def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    from argparse import Namespace
    from borgmatic import get_parser
    parser = get_parser()
    namespace = Namespace()
    namespace.command = parser.parse_args([])

    def resolve_params(params):
        all_params = set()
        for param in params:
            if isinstance(param, argparse.ArgumentParser):
                all_params |= resolve_params(param._actions)
            else:
                all_params.add(param)
        return all_params

    def get_short_long_opts():
        opts = set()
        for param in namespace.command.params.values():
            if isinstance(param.opts, list):
                opts.update(param.opts)
            else:
                opts.add(param.opts)
        return [o[1:] for o in opts if o.startswith('-')]

    def get_positional_args():
        positions = set()
        for param in namespace.command.params.values():
            if isinstance(param.opts, list):
                positions.update(param.opts)
            elif param.opts is not None:
                positions.add(param.opts[1:])
        return [p for p in positions if p.startswith('-')]

    def get_subcommand_names():
        subcommands = set()
        for param in namespace.command.params.values():
            if isinstance(param, argparse.ArgumentParser):
                subcommands.add(param.prog.split()[-1])
        return list(subcommands)

    short_long_opts = get_short_long_opts()
    positional_args = get_positional_args()
    subcommand_names = get_subcommand_names()
    completion_script = """_%s()
{
{opts}
%s
}
""" % (
    namespace.command.prog.split()[-1],
    " ".join(
        f"""-{id} 'Required param {name}'
    COMPREPLY=( $(compgen -W '{ordered_list})" """
        for id, name in enumerate(short_long_opts, start=1))
    )
    """
    COMPON="@+)
    _filedir "@(omc)"
}
"""
)
    for subcommand in subcommand_names:
        completion_script = completion_script.replace(
            f'^{subcommand}',
            _filedir '@(omc)'
        )

    return completion_script.strip()

def parse_arguments(*unparsed_arguments):
    """Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    global_parser = argparse.ArgumentParser(description='Global arguments.')
    subparsers = global_parser.add_subparsers(help='Sub-command help.')

    parser_1 = subparsers.add_parser('parser_1', help='Parser 1 help.')
    parser_1.add_argument('--option_1', required=True, help='Option 1 help.')

    parser_2 = subparsers.add_parser('parser_2', help='Parser 2 help.')
    parser_2.add_argument('--option_2', required=True, help='Option 2 help.')

    args = global_parser.parse_known_args(unparsed_arguments)

    if args.option_1:
        return {'parser_1': args}
    elif args.option_2:
        return {'parser_2': args}
    else:
        return {'global': args}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = []

    for subparser_name, subparser in subparsers.items():
        try:
            parsed_arguments[subparser_name] = subparser.parse_known_args(unparsed_arguments)
            break
        except argparse.ArgumentError:
            pass
        except Exception as e:
            raise

    for subparser_name, subparser_arguments in parsed_arguments.items():
        remaining_arguments.extend(subparser_arguments.get('unparsed_arguments', []))

    return parsed_arguments, remaining_arguments

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    merged_dict = {}
    for d in dicts:
        for key, value in d.items():
            if key in merged_dict:
                merged_dict[key] += value
            else:
                merged_dict[key] = value
    return merged_dict

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Check if url_args is empty
    if not url_args:
        return url

    # Check if url is a string
    if not isinstance(url, str):
        raise TypeError("URL must be a string")

    # Replace any URL items with values in url_args
    for key, value in url_args.items():
        if isinstance(value, (list, tuple)):
            value = "|".join(value)
        url = url.replace("{" + key + "}", value)

    return url

