def vertex3tuple(vertices):
    """
    return 3 points for each vertex of the polygon. This will include the vertex
    and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        return [
            (vertices[i - 1], vertices[i], vertices[(i + 1) % len(vertices)])
            for i in range(len(vertices))
        ]
    except IndexError:
        raise ValueError("The input list must contain at least 3 vertices")

