    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = '1' if sys.platform.startswith('linux') else '0'
    elif platform == '1':
        raise ValueError("Platform '1' is not supported.")
    elif platform == '0':
        raise ValueError("Platform '0' is not supported.")
    else:
        raise ValueError("Invalid platform value.")

    pattern = r"[\s"]+" if platform == '1' else r"\s+"
    parts = re.split(pattern, s)
    return list(filter(None, parts))

