def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        number, unit = frequency.split(" ")
        if unit == "weeks":
            return datetime.timedelta(weeks=int(number))
        elif unit == "days":
            return datetime.timedelta(days=int(number))
        elif unit == "hours":
            return datetime.timedelta(hours=int(number))
        elif unit == "minutes":
            return datetime.timedelta(minutes=int(number))
        elif unit == "seconds":
            return datetime.timedelta(seconds=int(number))
        else:
            raise ValueError("Invalid unit of time")
    except ValueError:
        raise ValueError("Cannot parse frequency")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        socket.inet_pton(socket.AF_INET, host)
    except socket.error:
        try:
            socket.inet_pton(socket.AF_INET6, host)
        except socket.error:
            return False
        return True
    return host == "127.0.0.1" or host == "::1"

def make_find_paths(find_paths):
