def validate_from_content(cls, spec_content=None):
    """Validates that spec (YAML) content has all required fields.

    :param spec_content: Content of the spec file
    :raise IRValidatorException: When mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    if spec_content is None:
        raise IRValidatorException("Missing spec content.")

    data = yaml.safe_load(spec_content)

    # Validate required fields
    for field in cls.REQUIRED_FIELDS:
        if field not in data:
            raise IRValidatorException(f"Missing required field '{field}' in spec file.")

    # Validate types
    for field, typ in cls.TYPES.items():
        if not isinstance(data[field], typ):
            raise IRValidatorException(f"Invalid type for field '{field}': expected {typ}, got {type(data[field])}.")

    return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise TypeError("Missing parameter 'yaml_file'.")

    with open(yaml_file) as file:
        data = yaml.load(file, Loader=yaml.FullLoader)

    if data is None:
        raise IRValidatorException("Failed to parse YAML file.")

    # Verify schema
    if 'schema' not in data:
        raise IRValidatorException("Missing 'schema' field in YAML file.")
    schema = data['schema']

    # Verify schema version
    if 'schema_version' not in schema:
        raise IRValidatorException("Missing 'schema_version' field in YAML file.")
    if schema['schema_version'] != cls.SCHEMA_VERSION:
       raise IRValidatorException("Unsupported schema version.")

    # Verify schema fields
    if 'fields' not in schema:
        raise IRValidatorException("Missing 'fields' field in YAML file.")
    fields = schema['fields']

    # Verify required fields
    for field in fields:
         if 'name' not in field:
            raise IRValidatorException("Missing 'name' field in YAML file.")
         if 'type' not in field:
            raise IRValidatorException("Missing 'type' field in YAML file.")
         if field['type'] == 'date':
             if 'format' not in field:
                 raise IRValidatorException("Missing 'format' field in YAML file for 'date' type.")

    return data

